import java.io.InputStreamReader;
import java.io.IOException;

public class G {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        int s = Integer.parseInt(parts[2]) - 1;
        long t = Long.parseLong(parts[3]);
        int[] next = new int[n];
        for (int i = 0; i < n; i++) {
            next[i] = -1;
        }
        while (t % n != 0) {
            if (s < m) s += t % n;
            else s += n - (t % n);
            s %= n;
            t--;
        }
        long cycles = t / n;
        int prevs = s;
        while (cycles > 0 && next[s] == -1) {
            for (int i = n - 1; i > 0; i--) {
                if (s < m) s += i;
                else s += n - i;
                if (s >= n) s -= n;
            }
            next[prevs] = s;
            prevs = s;
            cycles--;
        }
        if (cycles > 0) {
            long cycleCount = 1;
            prevs = s;
            while (next[prevs] != s) {
                cycleCount++;
                prevs = next[prevs];
            }
            long total = cycles % cycleCount;
            for (int i = 0; i < total; i++) {
                s = next[s];
            }
        }
        System.out.println(s + 1);
        br.close();
    }
