    long long cycles = t / n;
    int prevs = s;

    while (cycles > 0 && next[s] == -1) {
        for (int i = n - 1; i > 0; i--) {
            if (s < m) s += i;
            else s += n - i;
            if (s >= n) s -= n;
        }
        next[prevs] = s;
        prevs = s;
        cycles--;
    }

    if (cycles > 0) {
        long long cycleCount = 1;
        prevs = s;
        while (next[prevs] != s) {
            cycleCount++;
            prevs = next[prevs];
